head.script:
scwin.vScrenID = "ULDFIS00300_P2.xml";
// 전역 변수 선언
scwin.comCd = ""; // 기업코드
scwin.basYymm = ""; // 결산년월

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
   scwin.param = $c.data.getParameter();
   scwin.comCd   = scwin.param.comCd;
   scwin.basYymm = scwin.param.basYymm;
   scwin.search(); //조회

};

scwin.onpageunload = function() {

};

// WebSquare 컴포넌트 이벤트 함수
//팝업닫기
scwin.img_Close_onclick = function (e) {
    $c.win.closePopup();
};

// 일반 함수
/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dlt_SpeclablContnRes.removeAll();
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    return true;
};

/**
 * 특기사항팝업 조회
 */
scwin.search = async function() {

    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    let url = "/api/listing/nice/individual-notes/audit-opinion/remark-detail?kisCd="+scwin.comCd+"&acntclsDt="+scwin.basYymm;
    $c.sbm.setAction(sbm_dlt_SpeclablContn, url);
    await $c.sbm.execute(sbm_dlt_SpeclablContn);
    scwin.appendContents();
};

/**
 * 컨텐츠 append
 */
scwin.appendContents = function() {

    let strContent = "<div style='overflow-x:hidden;width:100%;height:410px;font-family:돋움체;'>";
    for (let nRow = 0; nRow < dlt_SpeclablContnRes.getRowCount(); nRow++) {
        strContent = strContent + dlt_SpeclablContnRes.getCellData(nRow, "ctnt");
    }
    strContent = strContent + "</div>";

    let grpCtntObj = $p.getComponentById("grp_Ctnt").render;

    grpCtntObj.innerHTML = strContent;
    grp_Ctnt.setStyle("border", "1px solid blue");
    grp_Ctnt.setStyle("magin-top", "30px");

};
